interface WorkflowPipelineConfigValue {
  tenantConfigType?: ConfigType;      // opsional; default: <STAGE>_STABLE
  pipelines: WorkflowPipelineEntry[];
}

interface PipelineEntry {
  name: string;                       // serviceName executor di registry
  config: unknown;                    // bentuk tergantung executor
  andCondition?: TenantValidationConditionEntry[]; // semua harus lolos
  orCondition?: TenantValidationConditionEntry[];  // minimal satu lolos (jika ada)
}

interface WorkflowPipelineEntry extends PipelineEntry {
  service?: string;                   // duplikat name; TIDAK dibaca apa pun
}

// configurations/tenant-configuration/data/tenant-configuration.data.ts
type ValidationOperator = 'EQUALS' | 'NOT_EQUALS' | '=' | '!=' | '<' | '<=' | '>' | '>=';
interface TenantValidationCondition { left: unknown; operator: ValidationOperator; right: unknown; }
interface TenantValidationWhen { when: TenantValidationCondition; }
type TenantValidationConditionEntry = TenantValidationWhen | TenantValidationCondition;

interface LifecycleStepConfig<TConfig = unknown> {
  service: string;          // nama di LifecycleServiceRegistry (Transformer, Decrypt, ...)
  event: string[];          // langkah hanya jalan bila event (workflowName) ada di sini
  config: TConfig;
  andCondition?: ValidationWhen[];   // format { when: {...} }
  orCondition?: ValidationWhen[];
}

{
  "beforeExecute": [
    {
      "event": ["CREATE_SCHEDULE_INTERVIEW", "RESCHEDULE_INTERVIEW", "ADD_FINAL_DECISION",
                "MOVE_TO_VACANCY", "SEND_FORM", "RESEND_FORM"],
      "service": "Decrypt",
      "config": { "paths": ["$candidate.emailEncrypted"] }
    },
    {
      "event": ["CREATE_SCHEDULE_INTERVIEW", "RESCHEDULE_INTERVIEW"],
      "service": "Transformer",
      "config": {
        "outputKey": "$satellitePayload.interview",
        "transform": "$requestBody.satellitePayload.interview"
      }
    },
    {
      "event": ["CREATE_SCHEDULE_INTERVIEW", "SEND_FORM", "RESEND_FORM"],
      "service": "Transformer",
      "config": {
        "outputKey": "$satellitePayload.formName",
        "transform": "$vacancyStage.stageType == 'ASSESSMENT' && 'Assessment Form' || vacancyStage.stageType == 'INTERVIEW' && 'Interview Form' || vacancyStage.stageType == 'ADMINISTRATIVE' && 'Administrative Form' || 'Submission Form'"
      }
    }
  ]
}
